UPDATE coupons
   SET status = #{nextStatus}
 WHERE id = #{id}
   AND status = #{currentStatus}

UPDATE coupons
   SET issued_quantity = issued_quantity + 1
 WHERE id = #{id}
   AND status = 'ACTIVE'
   AND issued_quantity < total_quantity
   AND starts_at <= #{now}
   AND expires_at > #{now}

