WHERE c.status = 'ACTIVE'
  AND c.starts_at <= #{now}
  AND c.expires_at > #{now}
ORDER BY c.expires_at ASC, c.id DESC


WHERE mc.member_id = #{memberId}
  AND mc.status = 'AVAILABLE'
  AND c.status = 'ACTIVE'
  AND c.starts_at <= #{now}
  AND c.expires_at > #{now}
ORDER BY c.expires_at ASC, mc.id DESC

